const extractNode = $node["Gemini: Extract Lead Info"];

if (extractNode && extractNode.json.candidates && extractNode.json.candidates[0]) {
  try {
    const part = extractNode.json.candidates[0].content.parts[0];
    let parsed;
    if (typeof part.text === 'object' && part.text !== null) {
      // Already a parsed object
      parsed = part.text;
    } else if (typeof part.text === 'string') {
      // Extract JSON by finding first { and last } — handles any trailing garbage
      const firstBrace = part.text.indexOf('{');
      const lastBrace = part.text.lastIndexOf('}');
      if (firstBrace === -1 || lastBrace === -1) {
        throw new Error('No JSON object found in Gemini response: ' + part.text.substring(0, 200));
      }
      const cleaned = part.text.substring(firstBrace, lastBrace + 1);
      parsed = JSON.parse(cleaned);
    } else {
      throw new Error('Unexpected response format from Gemini');
    }
    return [{
      json: {
        status: 'processed',
        transcript: parsed.transcript || 'No transcript provided',
        summary: parsed.summary || 'No summary provided',
        intent: parsed.intent || 'Unknown intent',
        conversion_score: Number(parsed.conversion_score) || 0,
        lead_info: parsed.lead_info || {}
      }
    }];
  } catch (e) {
    return [{
      json: {
        error: 'Failed to parse Gemini JSON response: ' + e.message
      }
    }];
  }
}

return [{
  json: {
    error: 'No response text found from Gemini'
  }
}];

